<?php
function padHtmlTableRead($text,$options){
 if(array_diff(array_keys($options),['table','header']))padFormatFail(0,'unknown HTML table option');$selector=$options['table']??0;$header=$options['header']??'first';if((!is_int($selector)||$selector<0)&&(!is_string($selector)||!preg_match('/^#[A-Za-z_][A-Za-z0-9_.:-]*$/D',$selector)))padFormatFail(0,'table must be a zero-based index or #id');if(!in_array($header,['first','none'],TRUE))padFormatFail(0,'header is first or none');if(strlen($text)>4194304||!mb_check_encoding($text,'UTF-8'))padFormatFail(0,'HTML must be UTF-8 and at most 4 MiB');if(preg_match('/<!ENTITY\b|<!DOCTYPE[^>]*(?:SYSTEM|PUBLIC)/i',$text))padFormatFail(0,'external declarations are unsupported');if(!class_exists('DOMDocument'))padFormatFail(0,'HTML tables require DOM');
 $previous=libxml_use_internal_errors(TRUE);try{$dom=new DOMDocument();$ok=$dom->loadHTML('<?xml encoding="UTF-8">'.$text,LIBXML_NONET|LIBXML_COMPACT);$errors=libxml_get_errors();if(!$ok)padFormatFail($errors[0]->line??0,'HTML table document cannot be parsed');}finally{libxml_clear_errors();libxml_use_internal_errors($previous);}$xpath=new DOMXPath($dom);$tables=$xpath->query('//table');$table=NULL;if(is_int($selector))$table=$tables->item($selector);else foreach($tables as $candidate)if($candidate->getAttribute('id')===substr($selector,1)){if($table)padFormatFail($candidate->getLineNo(),'duplicate table selector '.$selector);$table=$candidate;}if(!$table)padFormatFail(0,'selected table '.(string)$selector.' was not found');
 $rows=$xpath->query('./tr|./thead/tr|./tbody/tr|./tfoot/tr',$table);if($rows->length>10000)padFormatFail($table->getLineNo(),'table exceeds 10000 rows');$grid=[];$cells=0;$width=0;$textBytes=0;
 foreach($rows as $r=>$row){$c=0;foreach($xpath->query('./td|./th',$row) as $cell){while(isset($grid[$r][$c]))$c++;$span=[];foreach(['rowspan'=>1000,'colspan'=>256] as $name=>$max){$value=$cell->hasAttribute($name)?$cell->getAttribute($name):'1';if(!preg_match('/^[1-9][0-9]*$/D',$value)||(float)$value>$max)padFormatFail($cell->getLineNo(),'table '.(string)$selector.' has invalid '.$name);$span[$name]=(int)$value;}if($r+$span['rowspan']>$rows->length||$c+$span['colspan']>256)padFormatFail($cell->getLineNo(),'table span exceeds row/column bounds');$clone=$cell->cloneNode(TRUE);$remove=[];foreach(['script','style','table'] as $name)foreach($clone->getElementsByTagName($name) as $node)$remove[]=$node;foreach($remove as $node)if($node->parentNode)$node->parentNode->removeChild($node);$value=$clone->textContent;if(($textBytes+=strlen($value)*$span['rowspan']*$span['colspan'])>8388608)padFormatFail($cell->getLineNo(),'expanded table text exceeds 8 MiB');
 for($rr=$r;$rr<$r+$span['rowspan'];$rr++)for($cc=$c;$cc<$c+$span['colspan'];$cc++){if(isset($grid[$rr][$cc]))padFormatFail($cell->getLineNo(),'overlapping table spans');if(++$cells>100000)padFormatFail($cell->getLineNo(),'expanded table exceeds 100000 cells');$grid[$rr][$cc]=$value;}$c+=$span['colspan'];$width=max($width,$c);}}
 if(!$grid)return [];if($width*$rows->length>100000)padFormatFail($table->getLineNo(),'rectangular table exceeds 100000 cells');$dense=[];for($r=0;$r<$rows->length;$r++){$values=[];for($c=0;$c<$width;$c++)$values[]=$grid[$r][$c]??NULL;$dense[]=$values;}
 $names=$header==='first'?array_map(fn($v)=>trim((string)$v),array_shift($dense)):array_map(fn($i)=>'column'.$i,range(1,$width));if(in_array('',$names,TRUE)||count(array_unique($names,SORT_STRING))!==count($names))padFormatFail($table->getLineNo(),'table headers must be nonempty and unique');return array_map(fn($row)=>array_combine($names,$row),$dense);
}
